// 退役 service worker 的「自注销」脚本（PWA kill switch）。
//
// 背景：本站在迁移到 Astro 之前是 Jekyll + Chirpy，当时开启了 PWA
// （`pwa.enabled: true` / `pwa.cache.enabled: true`），在 `/sw.min.js`
// 注册了一个 scope 为 `/`、cache-first 的 service worker，把同源所有
// GET（包括 HTML 导航）都写进缓存。
//
// 迁移后 `/sw.min.js` 不再存在（404），于是浏览器对 SW 脚本的更新检查
// 一直失败，那个旧 worker 就永远不会被替换或注销，继续把缓存里的旧
// Jekyll 页面返回给访问者——表现就是「push 上去但站点不更新」。
//
// 这里在完全相同的路径上提供一个新脚本，让更新检查得以成功：新 worker
// 安装后立即清空所有缓存、注销自己，并强制重新加载打开的标签页。等所有
// 受影响的浏览器都跑过一次之后，这个文件本身就不再被请求了。
//
// 注意：故意不实现 fetch 处理器——注销完成前也未控制请求，页面直接走网络。

self.addEventListener('install', () => {
  // 不等待旧的 worker 让位，直接进入 activate。
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      // 1. 清掉 Chirpy 及任何历史遗留的缓存。
      const cacheKeys = await caches.keys();
      await Promise.all(cacheKeys.map((key) => caches.delete(key)));

      // 2. 注销自己，让后续请求回到正常网络路径。
      await self.registration.unregister();

      // 3. 强制所有已打开的标签页重新加载，拿到新站点。
      const clients = await self.clients.matchAll({ type: 'window' });
      for (const client of clients) {
        await client.navigate(client.url);
      }
    })(),
  );
});
